def neighbors(count, edges):
    upper = [[] for _ in range(count)]
    lower = [[] for _ in range(count)]
    for first, second in edges:
        lower[first].append(second)
        upper[second].append(first)
    return upper, lower


def acyclic_order(count, edges):
    upper, lower = neighbors(count, edges)
    remaining = set(range(count))
    head, tail = [], []
    while remaining:
        indegree = {v: sum(u in remaining for u in upper[v]) for v in remaining}
        outdegree = {v: sum(w in remaining for w in lower[v]) for v in remaining}
        sinks = [v for v in remaining if outdegree[v] == 0]
        sources = [v for v in remaining if indegree[v] == 0]
        if sinks:
            chosen = min(sinks)
            tail.insert(0, chosen)
        elif sources:
            chosen = min(sources)
            head.append(chosen)
        else:
            chosen = min(remaining, key=lambda v: (indegree[v] - outdegree[v], v))
            head.append(chosen)
        remaining.remove(chosen)
    return head + tail


def initial_heights(count, upper, lower, method, width):
    heights = [None] * count
    labels = None
    if method == "coffman":
        labels = [None] * count
        for label in range(1, count + 1):
            candidates = [v for v in range(count)
                          if labels[v] is None and all(labels[u] is not None for u in upper[v])]
            chosen = min(candidates, key=lambda v: (sorted((labels[u] for u in upper[v]), reverse=True), v))
            labels[chosen] = label
        current = 0
        occupied = 0
        for _ in range(count):
            candidates = [v for v in range(count)
                          if heights[v] is None and all(heights[w] is not None for w in lower[v])]
            chosen = max(candidates, key=lambda v: labels[v])
            if occupied == width or any(heights[w] == current for w in lower[chosen]):
                current += 1
                occupied = 0
            heights[chosen] = current
            occupied += 1
    else:
        for _ in range(count):
            chosen = next(v for v in range(count)
                          if heights[v] is None and all(heights[w] is not None for w in lower[v]))
            heights[chosen] = max((heights[w] + 1 for w in lower[chosen]), default=0)
    return heights, labels


def assign_heights(count, edges, settings):
    upper, lower = neighbors(count, edges)
    heights, labels = initial_heights(count, upper, lower, settings["layering"], settings["width"])
    dummies_before = sum(heights[a] - heights[b] - 1 for a, b in edges)
    record = []
    rounds = 0

    def promote(vertex):
        difference = 0
        for predecessor in upper[vertex]:
            if heights[predecessor] == heights[vertex] + 1:
                difference += promote(predecessor)
        heights[vertex] += 1
        return difference + len(lower[vertex]) - len(upper[vertex])

    if settings["promotion"] == "on":
        while True:
            rounds += 1
            accepted = 0
            for vertex in range(count):
                if not upper[vertex]:
                    continue
                saved = heights.copy()
                difference = promote(vertex)
                if difference < 0:
                    accepted += 1
                    record.append((rounds, vertex, difference))
                else:
                    heights[:] = saved
            if accepted == 0:
                break
    return heights, labels, dummies_before, rounds, record

class Canvas:
    def __init__(self, direction, main_length, secondary_length):
        self.direction = direction
        self.main_length = main_length
        self.vertical = direction in ("TB", "BT")
        self.rows = main_length if self.vertical else secondary_length
        self.columns = secondary_length if self.vertical else main_length
        self.line_bits = {}
        self.arrows = {}
        self.boxes = {}
        self.highlighted = set()
        self.main_character = "|" if self.vertical else "-"
        self.secondary_character = "-" if self.vertical else "|"

    def cell(self, main, secondary):
        if self.direction in ("BT", "RL"):
            main = self.main_length - 1 - main
        return (main, secondary) if self.vertical else (secondary, main)

    def add_line(self, main, secondary, character):
        cell = self.cell(main, secondary)
        bit = {"|": 1, "-": 2, "+": 4}[character]
        self.line_bits[cell] = self.line_bits.get(cell, 0) | bit

    def main_line(self, start, end, secondary):
        for main in range(start, end + 1):
            self.add_line(main, secondary, self.main_character)

    def segment(self, start, gap, first, second, offset):
        if first == second:
            self.main_line(start, start + gap - 1, first)
            return
        self.main_line(start, start + offset - 1, first)
        self.add_line(start + offset, first, "+")
        self.add_line(start + offset, second, "+")
        for secondary in range(min(first, second) + 1, max(first, second)):
            self.add_line(start + offset, secondary, self.secondary_character)
        self.main_line(start + offset + 1, start + gap - 1, second)

    def arrow(self, point, reversed_edge):
        forward = {"TB": "v", "BT": "^", "LR": ">", "RL": "<"}
        backward = {"TB": "^", "BT": "v", "LR": "<", "RL": ">"}
        self.arrows[self.cell(*point)] = (backward if reversed_edge else forward)[self.direction]

    def highlight_route(self, points):
        for (row1, column1), (row2, column2) in zip(points, points[1:]):
            row_step = (row2 > row1) - (row2 < row1)
            column_step = (column2 > column1) - (column2 < column1)
            distance = abs(row2 - row1) + abs(column2 - column1)
            for step in range(distance + 1):
                self.highlighted.add((row1 + step * row_step, column1 + step * column_step))

    def box(self, label, band_start, coordinate, left, on_path):
        text = "{" + label + "}" if on_path else "[" + label + "]"
        if self.vertical:
            row, column = self.cell(band_start, coordinate - left)
        elif self.direction == "LR":
            row, column = coordinate, band_start
        else:
            row, column = coordinate, self.main_length - band_start - len(text)
        for offset, character in enumerate(text):
            self.boxes[row, column + offset] = character

    def character(self, row, column):
        cell = row, column
        if cell in self.boxes:
            return self.boxes[cell]
        if cell in self.arrows:
            return self.arrows[cell]
        if cell in self.highlighted:
            return "#"
        return {0: " ", 1: "|", 2: "-", 4: "+"}.get(self.line_bits.get(cell, 0), "+")

    def crossing_cells(self):
        return sum(bits & 3 == 3 for bits in self.line_bits.values())

    def drawing_lines(self):
        lines = ["    " + "".join(str(column % 10) for column in range(self.columns))]
        for row in range(self.rows):
            characters = "".join(self.character(row, column) for column in range(self.columns))
            lines.append((f"{row:3d} " + characters).rstrip())
        return lines

from collections import namedtuple

import crossing


VARIANTS = ("ul", "ur", "dl", "dr")
Result = namedtuple("Result", "x left right aligned blocks widths smallest conflicts")


def mark_conflicts(orders, upper, node_count, position):
    marked = set()
    for layer in range(len(orders) - 1):
        above, below = orders[layer:layer + 2]
        first_bound = 0
        start = 0
        for last, vertex in enumerate(below):
            inner = vertex >= node_count and upper[vertex][0] >= node_count
            if not inner and last != len(below) - 1:
                continue
            last_bound = position[upper[vertex][0]] if inner else len(above) - 1
            for following in below[start:last + 1]:
                for previous in upper[following]:
                    if position[previous] < first_bound or position[previous] > last_bound:
                        marked.add((previous, following))
            start = last + 1
            first_bound = last_bound
    return marked


def alignment(variant, orders, upper, lower, marked, count):
    scan = [list(layer) if variant[1] == "l" else list(reversed(layer)) for layer in orders]
    rank = crossing.positions(scan)
    root = list(range(count))
    align = list(range(count))
    layers = range(len(orders)) if variant[0] == "u" else range(len(orders) - 1, -1, -1)
    reference = upper if variant[0] == "u" else lower
    for layer in list(layers)[1:]:
        boundary = -1
        for vertex in scan[layer]:
            neighbors = sorted(reference[vertex], key=rank.get)
            if not neighbors:
                continue
            for middle in ((len(neighbors) - 1) // 2, len(neighbors) // 2):
                neighbor = neighbors[middle]
                segment = (neighbor, vertex) if variant[0] == "u" else (vertex, neighbor)
                if align[vertex] == vertex and segment not in marked and boundary < rank[neighbor]:
                    align[neighbor] = vertex
                    root[vertex] = root[neighbor]
                    align[vertex] = root[vertex]
                    boundary = rank[neighbor]
    return root, scan


def compact(root, scan, variant, left, right, node_count, settings):
    blocks = sorted(set(root))
    outgoing = {block: {} for block in blocks}
    incoming = {block: {} for block in blocks}
    for layer in scan:
        for first, second in zip(layer, layer[1:]):
            a, b = (first, second) if variant[1] == "l" else (second, first)
            gap = settings["node_sep"] if a < node_count and b < node_count else settings["dummy_sep"]
            distance = right[a] + left[b] + 1 + gap
            origin, target = root[first], root[second]
            distance = max(distance, outgoing[origin].get(target, distance))
            outgoing[origin][target] = distance
            incoming[target][origin] = distance
    pending = {block: len(incoming[block]) for block in blocks}
    ready = [block for block in blocks if pending[block] == 0]
    ordered = []
    first_coordinate = {}
    while ready:
        block = ready.pop()
        ordered.append(block)
        first_coordinate[block] = max((first_coordinate[previous] + distance
                                       for previous, distance in incoming[block].items()), default=0)
        for following in outgoing[block]:
            pending[following] -= 1
            if pending[following] == 0:
                ready.append(following)
    second_coordinate = {}
    for block in reversed(ordered):
        coordinate = first_coordinate[block]
        if outgoing[block]:
            coordinate = max(coordinate, min(second_coordinate[following] - distance
                                              for following, distance in outgoing[block].items()))
        second_coordinate[block] = coordinate
    sign = 1 if variant[1] == "l" else -1
    return [sign * second_coordinate[block] for block in root], len(blocks)


def assign(orders, upper, lower, widths, node_count, settings):
    count = len(widths)
    if settings["direction"] in ("TB", "BT"):
        left = [(width - 1) // 2 for width in widths]
        right = [width - 1 - extent for width, extent in zip(widths, left)]
    else:
        left = [0] * count
        right = [0] * count
    position = crossing.positions(orders)
    conflicts = mark_conflicts(orders, upper, node_count, position)
    layouts, blocks, bounds, spans = {}, {}, {}, {}
    for variant in VARIANTS:
        root, scan = alignment(variant, orders, upper, lower, conflicts, count)
        layout, block_count = compact(root, scan, variant, left, right, node_count, settings)
        low = min(value - extent for value, extent in zip(layout, left))
        high = max(value + extent for value, extent in zip(layout, right))
        layouts[variant] = layout
        blocks[variant] = block_count
        bounds[variant] = low, high
        spans[variant] = high - low + 1
    smallest = min(VARIANTS, key=spans.get)
    aligned = {}
    for variant in VARIANTS:
        side = 0 if variant[1] == "l" else 1
        shift = bounds[smallest][side] - bounds[variant][side]
        aligned[variant] = [value + shift for value in layouts[variant]]
    x = []
    for vertex in range(count):
        values = sorted(aligned[variant][vertex] for variant in VARIANTS)
        x.append((values[1] + values[2]) // 2)
    low = min(value - extent for value, extent in zip(x, left))
    x = [value - low for value in x]
    return Result(x, left, right, aligned, blocks, spans, smallest, conflicts)

def positions(orders):
    return {vertex: position for layer in orders for position, vertex in enumerate(layer)}


def accumulator(segments, position, lower_size):
    capacity = 1
    while capacity < lower_size:
        capacity *= 2
    tree = [0] * (2 * capacity - 1)
    count = 0
    pairs = sorted((position[p], position[q]) for p, q, edge in segments)
    for _, lower in pairs:
        index = lower + capacity - 1
        tree[index] += 1
        while index > 0:
            if index % 2 == 1:
                count += tree[index + 1]
            index = (index - 1) // 2
            tree[index] += 1
    return count


def brute_force(segments, position):
    count = 0
    for index, (p1, q1, _) in enumerate(segments):
        for p2, q2, _ in segments[index + 1:]:
            if (position[p1] - position[p2]) * (position[q1] - position[q2]) < 0:
                count += 1
    return count


def gap_counts(gaps, orders):
    position = positions(orders)
    return [accumulator(segments, position, len(orders[index + 1]))
            for index, segments in enumerate(gaps)]


def total(gaps, orders):
    return sum(gap_counts(gaps, orders))


def local_cost(gaps, orders, layer):
    position = positions(orders)
    count = 0
    for gap in (layer - 1, layer):
        if 0 <= gap < len(gaps):
            count += accumulator(gaps[gap], position, len(orders[gap + 1]))
    return count


def adjacent_cost(first, second, upper, lower, position):
    count = 0
    for neighbors in (upper, lower):
        for a in neighbors[first]:
            for b in neighbors[second]:
                count += position[a] > position[b]
    return count

from pathlib import Path
import re


DEFAULTS = {
    "layering": "longest", "width": 4, "promotion": "off",
    "heuristic": "barycenter", "sweeps": 12, "node_sep": 2,
    "dummy_sep": 1, "layer_gap": 3, "direction": "TB",
    "sifting": "off", "reduce": "off", "restarts": 0, "seed": 1,
}
CHOICES = {
    "layering": ("longest", "coffman"), "promotion": ("on", "off"),
    "heuristic": ("barycenter", "median"),
    "direction": ("TB", "BT", "LR", "RL"),
    "sifting": ("on", "off"), "reduce": ("on", "off"),
}
RANGES = {
    "width": (1, 40), "sweeps": (0, 50), "node_sep": (1, 9),
    "dummy_sep": (1, 9), "layer_gap": (2, 9),
    "restarts": (0, 9), "seed": (1, 2147483646),
}
INTEGER = re.compile(r"[0-9]{1,10}\Z")


def setting_value(name, word):
    if name in CHOICES:
        return word if word in CHOICES[name] else None
    if name in RANGES and INTEGER.fullmatch(word):
        value = int(word)
        low, high = RANGES[name]
        if low <= value <= high:
            return value
    return None


def input_lines(filename):
    contents = Path("input", filename).read_bytes().decode("ascii")
    for number, line in enumerate(contents.split("\n"), 1):
        if line and not line.startswith("#"):
            yield number, line.split(" ")


def read_defaults():
    settings = DEFAULTS.copy()
    for _, (name, word) in input_lines("params.txt"):
        settings[name] = setting_value(name, word)
    return settings


class Graph:
    def __init__(self, name, defaults):
        self.name = name
        self.settings = defaults.copy()
        self.nodes = {}
        self.edges = []
        self.edge_set = set()
        self.path = None
        self.self_loops = 0
        self.duplicates = 0
        self.error = None

    def accept(self, fields):
        kind = fields[0]
        if kind == "OPTION":
            name, word = fields[1:]
            value = setting_value(name, word)
            if value is None:
                return "bad_option"
            self.settings[name] = value
        elif kind == "NODE":
            node = int(fields[1])
            if node in self.nodes:
                return "duplicate_node"
            if len(self.nodes) == 40:
                return "too_many_nodes"
            self.nodes[node] = fields[2]
        else:
            first, second = map(int, fields[1:])
            if first not in self.nodes or second not in self.nodes:
                return "unknown_node"
            if kind == "PATH":
                self.path = first, second
            elif first == second:
                self.self_loops += 1
            elif (first, second) in self.edge_set:
                self.duplicates += 1
            else:
                self.edge_set.add((first, second))
                self.edges.append((first, second))
        return None


def read_graphs(defaults):
    graphs = []
    for number, fields in input_lines("graphs.txt"):
        if fields[0] == "GRAPH":
            graph = Graph(fields[1], defaults)
            graphs.append(graph)
        elif fields[0] == "END":
            if graph.error is None and not graph.nodes:
                graph.error = "no_nodes", number
        elif graph.error is None:
            error = graph.accept(fields)
            if error is not None:
                graph.error = error, number
    return graphs
